DROP TABLE IF EXISTS "product_group_items";
DROP TABLE IF EXISTS "product_groups";
ALTER TABLE "access_links" DROP COLUMN IF EXISTS "product_group_id";

CREATE TABLE "product_groups" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" uuid NOT NULL,
  "group_no" integer NOT NULL,
  "group_name" varchar(50) NOT NULL,
  "option_product_id" uuid NOT NULL,
  "sort" integer NOT NULL DEFAULT 0,
  CONSTRAINT "UQ_product_group_option" UNIQUE ("product_id", "group_no", "option_product_id"),
  CONSTRAINT "CHK_product_group_no" CHECK ("group_no" > 0),
  CONSTRAINT "CHK_product_group_self" CHECK ("product_id" <> "option_product_id")
);

CREATE INDEX "IDX_product_groups_product_order"
  ON "product_groups" ("product_id", "group_no", "sort", "id");
CREATE INDEX "IDX_product_groups_option_product"
  ON "product_groups" ("option_product_id");
